// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, string calldata description) public {
        vm.assume(actor != address(0));
        // set jojoTeam to actor so they are authorized to call newEmergencyOracle
        vm.prank(address(this));
        c.jojoTeam = actor;

        // actor calls newEmergencyOracle
        vm.prank(actor);
        try c.newEmergencyOracle(description) returns (address newOracle) {
            // owner() of the new EmergencyOracle must be the calling actor
            (bool success, bytes memory data) = newOracle.staticcall(abi.encodeWithSignature("owner()"));
            assertTrue(success);
            address oracleOwner = abi.decode(data, (address));
            assertTrue(oracleOwner == actor);
        } catch {
            // the call should not revert
            assertTrue(false);
        }
    }
}
